let bank: Float32Array | null = null;

/** A preset's values in control units (x 256; the velocity targets as they are), or null. */
export function dpPresetValues(i: number): number[] | null {
  if (!bank) {
    const s = atob(BANK);
    const b = new Uint8Array(s.length);
    for (let k = 0; k < s.length; k++) b[k] = s.charCodeAt(k);
    bank = new Float32Array(b.buffer);
  }
  if (!Number.isInteger(i) || i < 0 || i >= DP_PRESET_NAMES.length) return null;
  return Array.from(bank.subarray(i * 38, i * 38 + 38), (x, k) => (k >= 30 && k <= 33 ? x : x * 256));
}
